class Node {
    int val; Node next;
    Node(int v) { val = v; }
}
static Node reverseList(Node head) {
    Node prev = null, cur = head;
    while (cur != null) {
        Node nxt = cur.next;
        cur.next = prev;
        prev = cur; cur = nxt;
    }
    return prev;
}

